package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Takes the sheet's figures before the change writes anything, so RecordRollup can tell what it moved. */
public class SnapshotRollup {
    public void snapshot(@Val SheetResponse sheet, Rollup rollup, Out<RollupBefore> before) {
        before.set(new RollupBefore(rollup.snapshot(sheet.id())));
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;

/** After the change's own audit lines: a ROLLUP line per person whose figures moved, then TOTALS when the totals did. */
public class RecordRollup {
    public void record(@Val SheetResponse sheet, @Val RollupBefore before, @Val ChangedBy by, Rollup rollup) {
        rollup.record(sheet.id(), before.snapshot(), by);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@Val SheetResponse sheet, @PathVariable("personId") String personId,
            PersonRepository repository, Out<Person> person) throws BadRequestException {
        Person found = null;
        try {
            found = repository.find(sheet.id(), Long.parseLong(personId));
        } catch (NumberFormatException e) {
            // not an id: no such person
        }
        if (found == null) {
            throw new BadRequestException("No such person on this sheet");
        }
        person.set(found);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, PersonRepository repository, ObjectResponse<PersonResponse> response) {
        person.setClashing(repository.clashing(person));
        response.send(PersonResponse.from(person));
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonHeads } from '../../slots/defs/personRow';
import { peopleKey, usePeople, type Person } from '../people/people.slot';
import { personActionKey, useLastPersonAction } from '../people/personAction';
import { useUser } from '../session/useSession';

function RetireHeads() {
  return (
    <>
      <th>Retired</th>
      <th>Retired from</th>
      <th />
    </>
  );
}

// Whether the person is retired and from when, and the date and button that retire them (a blank date: the
// sheet's today). A person with a retirement date counts as retired at once, whatever the date. A refusal shows
// on the person until the next action on their row.
function RetireCells({ sheetId, personId }: { sheetId: string; user: string; personId: number }) {
  const person = usePeople(sheetId).data?.find((p) => p.id === personId);
  const [date, setDate] = useState('');
  const [user] = useUser();
  const queryClient = useQueryClient();
  const retire = useMutation({
    mutationKey: personActionKey(sheetId, personId),
    mutationFn: (from: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/retire`, {
        date: from.trim(),
        by: user ?? '',
      }),
    onSuccess: async () => {
      setDate('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
  });
  const last = useLastPersonAction(sheetId, personId, retire.submittedAt);
  const retired = person?.retiredFrom != null;

  return (
    <>
      <td data-testid="person-retired">{retired ? 'yes' : 'no'}</td>
      <td data-testid="person-retired-from">{person?.retiredFrom ?? ''}</td>
      <td>
        <input
          type="date"
          data-testid="person-retire-date"
          value={date}
          onChange={(e) => {
            setDate(e.target.value);
            retire.reset();
          }}
        />{' '}
        <button type="button" data-testid="person-retire" disabled={retire.isPending} onClick={() => retire.mutate(date)}>
          Retire
        </button>
        {retire.isError && last && (
          <span data-testid="person-error" role="alert">
            {retire.error.message}
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonHeads.fill({ order: 40, Component: RetireHeads }),
  PersonCells.fill({ order: 40, Component: RetireCells }),
];
import { useMutationState } from '@tanstack/react-query';

/** The key every action on a person's row (a statement, a retirement) runs its mutation under, so the row shows
 *  one error at a time: the last action's. */
export const personActionKey = (sheetId: string, personId: number) => ['sheet', sheetId, 'person-action', personId] as const;

/** Whether the mutation (run under personActionKey) is the last action taken on the person's row: only that
 *  one's refusal shows, so the next action on the row removes the error of the one before. */
export function useLastPersonAction(sheetId: string, personId: number, submittedAt: number): boolean {
  const times = useMutationState({
    filters: { mutationKey: personActionKey(sheetId, personId) },
    select: (m) => m.state.submittedAt,
  });
  return submittedAt === Math.max(0, ...times);
}

